message.content:
{
  "description": "The creature is a quadrupedal animal shown in right-facing profile standing on a small patch of sandy, pebbly ground. Its overall body shape, fur, head, and hindquarters are those of a large wolf, with dense shaggy fur in gray, beige and white, a long bushy tail, and two hind legs with paw feet. Its dorsal surface from the top of the head down the neck and across the entire back is covered by a large, dark gray to black, hard, pitted and scratched carapace with scalloped and ridged edges and overlapping segmented plates. Its two forelimbs are furry at the top but terminate in large, dark, pitted, crustacean-like chelae with curved pincers that rest on the ground.",
  "parts": [
    {
      "part": "head",
      "looks_like": "wolf-like with an elongated muzzle, black nose, amber eyes, white fur around the muzzle and lower cheek, and gray-beige fur on the forehead and sides",
      "where": "at the front of the body, facing to the right"
    },
    {
      "part": "ears",
      "looks_like": "two upright, pointed, furry ears with dark interiors and light outer edges",
      "where": "on top of the head, one slightly behind the other in profile"
    },
    {
      "part": "legs",
      "looks_like": "four legs; the two hind legs are slender, furry, with angled wolf-like joints; the two front legs are thicker, furry on the upper portion and encased below in dark, bumpy, hard material ending in pincers",
      "where": "two hind legs under the rear body and two front legs under the chest and shoulders, all supporting the body on the ground"
    },
    {
      "part": "feet",
      "looks_like": "hind feet are wolf paws with visible dark claws and pads; front feet are not paws but large dark chelae, each with two thick curved pincers with black tips and a bumpy, pitted outer surface",
      "where": "at the bottom of each leg, in contact with the ground"
    },
    {
      "part": "tail",
      "looks_like": "long, thick, bushy and furry, predominantly gray with lighter underfur, tapering to a point",
      "where": "at the rear of the body, hanging down behind the hind legs"
    },
    {
      "part": "shell",
      "looks_like": "a large, dark gray-black, hard-looking carapace with a pitted, scratched surface, scalloped wavy edges with light tan rims, and small raised bumps along the margin",
      "where": "covering the entire back from the base of the neck to above the hindquarters, sitting on top of the fur"
    },
    {
      "part": "plates",
      "looks_like": "overlapping segmented dark plates with light edges and small pits/holes; spiky, triangular plates along the back of the neck, a small three-segment plate on the forehead between the ears, smaller plates on the side of the chest and on the hip, and thick bumpy sheaths covering the front limbs above the pincers",
      "where": "along the dorsal midline and neck, on the top of the head, on the sides of the torso, and encasing the lower front legs"
    },
    {
      "part": "fur and markings",
      "looks_like": "dense, shaggy fur in mixed gray, beige and white, longer and thicker around the neck, chest and tail, shorter on the legs and face",
      "where": "covering the head, neck, torso, legs and tail, visible everywhere not covered by the dark shell and plates"
    }
  ],
  "attached_objects": [],
  "animals": ["wolf", "crab"],
  "separate_bodies": 1,
  "heads": 1,
  "walking_legs": 4,
  "wings": 0,
  "extra_limb_pieces": 0,
  "tails": 1
}
